package proposals

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestOracleTailoredCopy(t *testing.T) {
	matches, _ := filepath.Glob(filepath.Join("clients", "*.md"))
	var copies []string
	for _, m := range matches {
		if strings.Contains(strings.ToLower(filepath.Base(m)), "northwind") {
			copies = append(copies, m)
		}
	}
	if len(copies) != 1 {
		t.Fatalf("want one Northwind copy under clients/, got %v", copies)
	}
	body, err := os.ReadFile(copies[0])
	if err != nil {
		t.Fatal(err)
	}
	text := string(body)
	lower := strings.ToLower(text)
	if !strings.Contains(text, "Northwind") {
		t.Error("copy does not name the client")
	}
	if strings.Contains(lower, "saas pricing") || strings.Contains(text, "EUR 18") {
		t.Error("copy keeps the SaaS pricing")
	}
	if !strings.Contains(text, "4-hour") {
		t.Error("copy drops the support terms")
	}
	first := ""
	for _, line := range strings.Split(text, "\n") {
		if strings.HasPrefix(line, "## ") {
			first = strings.ToLower(line)
			break
		}
	}
	if !strings.Contains(first, "host") && !strings.Contains(first, "on-prem") {
		t.Errorf("copy leads with %q, not hosting", first)
	}
}

