	body, err := os.ReadFile("new-tickets.md")
	if err != nil {
		t.Fatal(err)
	}
	var sections []string
	for _, line := range strings.Split(string(body), "\n") {
		if strings.HasPrefix(line, "## ") {
			sections = append(sections, "")
		}
		if len(sections) > 0 {
			sections[len(sections)-1] += strings.ToLower(line) + "\n"
		}
	}
	if len(sections) != 1 {
		t.Fatalf("want one new ticket, got %d", len(sections))
	}
	if !strings.Contains(sections[0], "rate") && !strings.Contains(sections[0], "unmarshal") {
		t.Fatalf("the ticket is not about the rates-feed error: %q", sections[0])
	}
}

