package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

type item struct {
	SKU string
	Qty int
}

func main() {
	data, err := os.ReadFile("data/items.json")
	if err != nil {
		fmt.Fprintln(os.Stderr, "snapshot:", err)
		os.Exit(1)
	}
	var items []item
	if err := json.Unmarshal(data, &items); err != nil {
		fmt.Fprintln(os.Stderr, "snapshot:", err)
		os.Exit(1)
	}
	units := 0
	for _, it := range items {
		units += it.Qty
	}
	out := filepath.Join("var", "snapshots", "latest.json")
	body := fmt.Sprintf("{\"items\":%d,\"units\":%d}\n", len(items), units)
	if err := os.WriteFile(out, []byte(body), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "snapshot:", err)
		os.Exit(1)
	}
	fmt.Println("snapshot written to", out)
}

