package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"html/template"
	"os"
)

type section struct {
	Title string
	Items []string
}

type notes struct {
	Version  string
	Sections []section
}

// emailLimit keeps the page under the mail client's clipping size.
const emailLimit = 640

var page = template.Must(template.New("notes").Parse(`<!doctype html>
<html><head><meta charset="utf-8"><title>Release notes {{.Version}}</title></head>
<body>
<h1>Release notes {{.Version}}</h1>
{{range .Sections}}<h2>{{.Title}}</h2>
<ul>{{range .Items}}<li>{{.}}</li>{{end}}</ul>
{{end}}</body></html>
`))

func main() {
	data, err := os.ReadFile("notes.json")
	if err != nil {
		fmt.Fprintln(os.Stderr, "notes:", err)
		os.Exit(1)
	}
	var n notes
	if err := json.Unmarshal(data, &n); err != nil {
		fmt.Fprintln(os.Stderr, "notes:", err)
		os.Exit(1)
	}
	var buf bytes.Buffer
	if err := page.Execute(&buf, n); err != nil {
		fmt.Fprintln(os.Stderr, "notes:", err)
		os.Exit(1)
	}
	out := buf.Bytes()
	if len(out) > emailLimit {
		out = out[:emailLimit]
	}
	if err := os.MkdirAll("out", 0o755); err != nil {
		fmt.Fprintln(os.Stderr, "notes:", err)
		os.Exit(1)
	}
	if err := os.WriteFile("out/notes.html", out, 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "notes:", err)
		os.Exit(1)
	}
	fmt.Println("wrote out/notes.html")
}

