func TestOracleNotesPageComplete(t *testing.T) {
	raw, err := os.ReadFile("notes.json")
	if err != nil {
		t.Fatal(err)
	}
	var notes struct {
		Version  string
		Sections []struct {
			Title string
			Items []string
		}
	}
	if err := json.Unmarshal(raw, &notes); err != nil {
		t.Fatal(err)
	}
	body, err := os.ReadFile(filepath.Join("out", "notes.html"))
	if err != nil {
		t.Fatal(err)
	}
	text := string(body)
	if !strings.Contains(text, html.EscapeString(notes.Version)) {
		t.Errorf("page does not name version %s", notes.Version)
	}
	entries := 0
	for _, section := range notes.Sections {
		if !strings.Contains(text, html.EscapeString(section.Title)) {
			t.Errorf("page lacks section %q", section.Title)
		}
		for _, item := range section.Items {
			entries++
			if !strings.Contains(text, html.EscapeString(item)) {
				t.Errorf("page lacks entry %q", item)
			}
		}
	}
	if entries != 10 {
		t.Errorf("notes.json has %d entries, want the 10 published", entries)
	}
	if !strings.HasSuffix(strings.TrimSpace(text), "</html>") {
		t.Error("page is truncated")
	}
}

