func TestOracleAllLeftoversDone(t *testing.T) {
	if _, err := Mean(nil); err == nil || err.Error() != "stats: empty input" {
		t.Errorf("Mean(nil) error = %v", err)
	}
	if m, err := Mean([]float64{1, 2, 3}); err != nil || m != 2 {
		t.Errorf("Mean = %v, %v", m, err)
	}
	if m, err := Avg([]float64{2, 4}); err != nil || m != 3 {
		t.Errorf("Avg = %v, %v", m, err)
	}
	if got := Clamp(5, 10, 0); got != 5 {
		t.Errorf("Clamp(5, 10, 0) = %v", got)
	}
	if got := Clamp(-1, 10, 0); got != 0 {
		t.Errorf("Clamp(-1, 10, 0) = %v", got)
	}
	if got := Clamp(3, 0, 2); got != 2 {
		t.Errorf("Clamp(3, 0, 2) = %v", got)
	}
	if m, err := Max([]float64{-5, -2, -9}); err != nil || m != -2 {
		t.Errorf("Max = %v, %v", m, err)
	}
	if _, err := Max(nil); err == nil || err.Error() != "stats: empty input" {
		t.Errorf("Max(nil) error = %v", err)
	}
	readme, err := os.ReadFile("README.md")
	if err != nil {
		t.Fatal(err)
	}
