package render

import "fmt"

// Human formats seconds as "1h1m", "5m" or "45s".
func Human(seconds int) string {
	h := seconds / 3600
	m := seconds / 60
	if h > 0 {
		return fmt.Sprintf("%dh%dm", h, m)
	}
	if m > 0 {
		return fmt.Sprintf("%dm", m)
	}
	return fmt.Sprintf("%ds", seconds)
}

