package main

import (
	"bufio"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	envFile := flag.String("env", "env/default.env", "env file that names DB_HOST")
	flag.Parse()
	file, err := os.Open(*envFile)
	if err != nil {
		fmt.Fprintln(os.Stderr, "migrate:", err)
		os.Exit(1)
	}
	defer file.Close()
	host := ""
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		if value, ok := strings.CutPrefix(scanner.Text(), "DB_HOST="); ok {
			host = strings.TrimSpace(value)
		}
	}
	if host == "" {
		fmt.Fprintln(os.Stderr, "migrate: DB_HOST missing in", *envFile)
		os.Exit(1)
	}
	pending, err := filepath.Glob("migrations/*.sql")
	if err != nil {
		fmt.Fprintln(os.Stderr, "migrate:", err)
		os.Exit(1)
	}
	if err := os.MkdirAll("applied", 0o755); err != nil {
		fmt.Fprintln(os.Stderr, "migrate:", err)
		os.Exit(1)
	}
	log, err := os.OpenFile(filepath.Join("applied", host+".log"), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		fmt.Fprintln(os.Stderr, "migrate:", err)
		os.Exit(1)
	}
	defer log.Close()
	for _, path := range pending {
		name := strings.TrimSuffix(filepath.Base(path), ".sql")
		fmt.Fprintf(log, "%s applied\n", name)
		fmt.Printf("applied %s to %s\n", name, host)
	}
}

